    m := m * (1 + (combat_v2_mech(p_b, p_unit, 'pack')->>'atk_per_foe')::numeric
                  * (select count(*) from combat_v2_units(p_state) q where q.side = 'enemy' and combat_v2_up(p_state->'enemies'->(q.id::int))));
  end if;
